<?php namespace App\Http\Controllers; use App\Models\{Message,Post}; class DashboardController extends Controller { public function __invoke(){ $user=auth()->user(); return view('dashboard',['feed'=>Post::with('creator.creatorProfile')->whereNotNull('published_at')->latest('published_at')->paginate(12),'unreadMessages'=>Message::where('recipient_id',$user->id)->whereNull('read_at')->count()]); } }
